<?php
require __DIR__.'/../bootstrap.php'; ensure_cms_schema();
$slug=trim((string)getv('slug',''));$st=db()->prepare("SELECT p.*,u.full_name author_name FROM cms_posts p LEFT JOIN users u ON u.id=p.author_id WHERE p.slug=? AND p.post_type='post' AND p.status='published' AND p.visibility='public' LIMIT 1");$st->execute([$slug]);$post=$st->fetch();if(!$post){render_http_error_page(404,'Post not found','This post may have moved or is no longer available.');exit; }
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['comment_submit'])){verify_csrf();if(!empty($post['comments_enabled'])){$name=trim((string)post('comment_name',''));$email=trim((string)post('comment_email',''));$content=trim((string)post('comment_content',''));$parentId=(int)post('comment_parent',0);if($parentId){$vp=db()->prepare("SELECT id FROM cms_comments WHERE id=? AND post_id=? AND status='approved'");$vp->execute([$parentId,(int)$post['id']]);if(!$vp->fetchColumn())$parentId=0;}if($name!==''&&$content!==''){db()->prepare('INSERT INTO cms_comments(post_id,parent_id,author_name,author_email,content,status,ip_hash,created_at,updated_at) VALUES(?,?,?,?,?,\'pending\',?,NOW(),NOW())')->execute([(int)$post['id'],$parentId?:null,$name,$email?:null,$content,hash('sha256',(string)($_SERVER['REMOTE_ADDR']??''))]);flash('success','Comment submitted for moderation.');redirect('/posts/?slug='.urlencode($slug).'#comments');}flash('error','Name and comment are required.');}}
$cats=cms_terms((int)$post['id'],'category');$tags=cms_terms((int)$post['id'],'tag');$cs=db()->prepare("SELECT * FROM cms_comments WHERE post_id=? AND status='approved' ORDER BY created_at ASC");$cs->execute([$post['id']]);$comments=$cs->fetchAll();$commentTree=cms_comment_children($comments);$title=$post['title'];public_header($title);
?><article class="about-section cms-public-post"><div class="eyebrow">POST</div><h1><?=e($post['title'])?></h1><div class="cms-post-meta">By <?=e($post['author_name']?:'PocketCat')?> · <?=e(date('F j, Y',strtotime($post['published_at']?:$post['updated_at'])))?></div><?php if(!empty($post['featured_image_url'])):?><img class="cms-featured-image" src="<?=e($post['featured_image_url'])?>" alt="<?=e($post['title'])?>"><?php endif;?><div class="cms-content"><?=$post['content']?></div><?php if($cats||$tags):?><div class="cms-taxonomy-line"><?php foreach($cats as $c):?><a href="/category/?slug=<?=urlencode($c['slug'])?>"><?=e($c['name'])?></a><?php endforeach;?><?php foreach($tags as $t):?><span>#<?=e($t['name'])?></span><?php endforeach;?></div><?php endif;?></article><section class="about-section" id="comments"><h2>Comments</h2><?php if($comments):?><div class="public-comments"><?php $renderComments=function($parent=0,$depth=0)use(&$renderComments,$commentTree){foreach(($commentTree[$parent]??[]) as $c):?><article class="public-comment comment-depth-<?=min(5,$depth)?>" id="comment-<?=$c['id']?>"><strong><?=e($c['author_name'])?></strong><small><?=e(date('M j, Y',strtotime($c['created_at'])))?></small><p><?=nl2br(e($c['content']))?></p><?php if($depth<4&& !empty($GLOBALS['post']['comments_enabled'])):?><button type="button" class="comment-reply-link" data-reply-to="<?=$c['id']?>">Reply</button><?php endif;?></article><?php $renderComments((int)$c['id'],$depth+1);endforeach;};$renderComments();?></div><?php else:?><p class="muted">No approved comments yet.</p><?php endif;?><?php if(!empty($post['comments_enabled'])):?><form method="post" class="card form-card comment-form"><?=csrf_field()?><input type="hidden" name="comment_submit" value="1"><h3 id="comment-form-title">Leave a comment</h3><input type="hidden" name="comment_parent" id="commentParent" value="0"><button type="button" class="comment-cancel-reply" id="cancelCommentReply" hidden>Cancel reply</button><label>Name<input name="comment_name" required maxlength="180"></label><label>Email <small>(optional)</small><input name="comment_email" type="email" maxlength="190"></label><label>Comment<textarea name="comment_content" rows="5" required maxlength="5000"></textarea></label><button class="btn">Submit for review</button></form><?php endif;?></section><script>document.querySelectorAll("[data-reply-to]").forEach(b=>b.addEventListener("click",()=>{const p=document.getElementById("commentParent"),f=document.getElementById("comment-form-title"),c=document.getElementById("cancelCommentReply");if(p)p.value=b.dataset.replyTo;if(f)f.textContent="Reply to comment #"+b.dataset.replyTo;if(c)c.hidden=false;document.getElementById("comments")?.scrollIntoView({behavior:"smooth",block:"start"});}));document.getElementById("cancelCommentReply")?.addEventListener("click",()=>{document.getElementById("commentParent").value="0";document.getElementById("comment-form-title").textContent="Leave a comment";document.getElementById("cancelCommentReply").hidden=true;});</script><?php public_footer();
